package com.hbm.machine.radar;
import com.hbm.item.coordinate.CoordinateItem;import com.hbm.multiblock.DummyableBlock;import com.hbm.radar.IRadarCommandReceiver;import com.hbm.registry.HbmSounds;import net.minecraft.core.BlockPos;import net.minecraft.sounds.SoundSource;import net.minecraft.world.entity.player.Player;import net.minecraft.world.level.Level;import net.minecraft.world.level.block.entity.BlockEntity;
/** Actual ItemRadarLinker resolves the real multiblock core and accepts radar-command receivers or radar screen. */
public final class RadarLinkerItem extends CoordinateItem{public static BlockEntity core(Level level,BlockPos pos){var state=level.getBlockState(pos);if(state.getBlock() instanceof DummyableBlock block){var p=block.findCore(level,pos);return p==null?null:level.getBlockEntity(p);}return level.getBlockEntity(pos);}@Override protected boolean canGrab(Level level,BlockPos pos){var tile=core(level,pos);return tile instanceof IRadarCommandReceiver||tile instanceof RadarScreenBlockEntity;}@Override protected BlockPos coordinates(Level level,BlockPos pos){return core(level,pos).getBlockPos();}@Override protected void targetSet(Level level,BlockPos pos,Player player){if(player!=null)level.playSound(null,player.getX(),player.getY(),player.getZ(),HbmSounds.get("item.techBleep"),SoundSource.PLAYERS,1,1);}}
